            ["wire.glueNothing"] = new[] { "Nothing to glue to there: click a plate or a part.", "U yerda yopishtiradigan narsa yoʻq: plastina yoki qismni bosing.", "Там не к чему приклеить: щёлкните пластину или деталь." },
            ["wire.glueFar"] = new[] { "Nothing near this point to glue it to: drag it onto a plate or a part first.", "Bu nuqta yonida yopishtiradigan narsa yoʻq: avval uni plastina yoki qism ustiga suring.", "Рядом с точкой не к чему приклеить: сначала перетащите её к пластине или детали." },
            ["chk.noBattery"] = new[] { "No battery: nothing has power.", "Batareya yoʻq: hech narsaga quvvat bormaydi.", "Нет батареи: ничего не получает питания." },
            ["chk.shortCircuit"] = new[] { "Short circuit: battery + and − are joined. The wires get hot and the cells drain fast.", "Qisqa tutashuv: batareyaning + va − uchlari ulangan. Simlar qiziydi va batareya tez tugaydi.", "Короткое замыкание: + и − батареи соединены. Провода греются, батарейки быстро садятся." },
            ["chk.driverUnpowered"] = new[] { "The L298N has no motor supply: wire battery + to +12V and battery − to GND.", "L298N ga motor quvvati kelmayapti: batareya + ni +12V ga, batareya − ni GND ga ulang.", "На L298N нет питания моторов: подключите + батареи к +12V, а − батареи к GND." },
            ["chk.noBoard"] = new[] { "No Arduino board: nothing runs your code.", "Arduino platasi yoʻq: kodingizni bajaradigan narsa yoʻq.", "Нет платы Arduino: код некому выполнять." },
            ["chk.board5vOvervoltage"] = new[] { "Battery + is on the Uno's 5V pin: about 6 V there burns the board (F7). Use VIN or the L298N's +5V.", "Batareya + Uno ning 5V piniga ulangan: u yerdagi taxminan 6 V platani kuydiradi (F7). VIN yoki L298N ning +5V chiqishidan foydalaning.", "+ батареи подключён к выводу 5V платы Uno: около 6 В сожгут плату (F7). Используйте VIN или +5V драйвера L298N." },
            ["chk.boardUnpowered"] = new[] { "The Uno has no power: wire its 5V to the L298N's +5V, or VIN to battery +.", "Uno ga quvvat kelmayapti: uning 5V pinini L298N ning +5V chiqishiga yoki VIN ni batareya + ga ulang.", "Плата Uno без питания: подключите её 5V к +5V драйвера L298N или VIN к + батареи." },
            ["chk.fiveVoltOnVin"] = new[]
            {
                "The L298N's +5V goes to the Uno's VIN, but VIN needs 7-12 V (it feeds the Uno's own 5 V regulator), so the Uno gets too little to run. Move that wire from VIN to the Uno's 5V pin.",
                "L298N ning +5V chiqishi Uno ning VIN piniga ulangan, lekin VIN ga 7-12 V kerak (u Uno ning oʻz 5 V stabilizatorini taʼminlaydi), shuning uchun Uno ishlashga yetarli quvvat olmaydi. Bu simni VIN dan Uno ning 5V piniga oʻtkazing.",
                "+5V драйвера L298N подключён к VIN платы Uno, но на VIN нужно 7–12 В (он питает собственный стабилизатор 5 В платы), поэтому Uno не хватает питания. Перенесите этот провод с VIN на вывод 5V платы Uno.",
            },
            ["chk.noGround"] = new[] { "No common ground: join a GND pin of the Uno to the battery's − (through the L298N's GND).", "Umumiy yer yoʻq: Uno ning GND pinini batareyaning − uchiga (L298N ning GND orqali) ulang.", "Нет общей земли: соедините GND платы Uno с − батареи (через GND драйвера L298N)." },
            ["chk.driver5vLow"] = new[] { "• The L298N's 5 V regulator needs about 7 V; from 4×AA it gives a little under 5 V. That works, as on the real kit.", "• L298N ning 5 V stabilizatoriga taxminan 7 V kerak; 4×AA dan u 5 V dan biroz kam beradi. Haqiqiy toʻplamdagidek ishlaydi.", "• Стабилизатору 5 В на L298N нужно около 7 В; от 4×AA он даёт чуть меньше 5 В. Это работает, как в настоящем наборе." },
            ["chk.pinsJoined"] = new[] { "Uno pins {0} and {1} are joined by wires: when one is HIGH and the other LOW, they fight.", "Uno ning {0} va {1} pinlari simlar bilan ulangan: biri HIGH, ikkinchisi LOW boʻlsa, ular bir-biriga qarshi ishlaydi.", "Выводы {0} и {1} платы Uno соединены: когда один HIGH, а другой LOW, они мешают друг другу." },
            ["chk.sonarOvervoltage"] = new[] { "Battery + is on the HC-SR04's VCC: more than 5.5 V burns the sensor (F26).", "Batareya + HC-SR04 ning VCC piniga ulangan: 5,5 V dan ortigʻi sensorni kuydiradi (F26).", "+ батареи подключён к VCC датчика HC-SR04: больше 5,5 В сожгут датчик (F26)." },
            ["chk.sonarUnpowered"] = new[] { "The HC-SR04 has no power: VCC needs 5 V and GND a ground.", "HC-SR04 ga quvvat kelmayapti: VCC ga 5 V, GND ga yer kerak.", "Датчик HC-SR04 без питания: на VCC нужно 5 В, а GND — на землю." },
            ["chk.ledNoGround"] = new[] { "{0}: its − pin is not on ground (GND).", "{0}: uning − pini yerga (GND) ulanmagan.", "{0}: вывод − не подключён к земле (GND)." },
            ["chk.ledPin"] = new[] { "{0}: its S pin is not wired to an Uno pin.", "{0}: S pini Uno pinlaridan biriga ulanmagan.", "{0}: вывод S не подключён к выводу Uno." },
            ["chk.servoUnpowered"] = new[] { "{0} has no power: V+ wants 5–6 V (the Uno's 5V, the L298N's +5V or the battery) and GND on ground.", "{0} taʼminotsiz: V+ ga 5–6 V (Uno 5V, L298N +5V yoki batareya) kerak, GND esa yerga ulanadi.", "{0} без питания: на V+ нужно 5–6 В (5V Uno, +5V L298N или батарея), а GND — на землю." },
            ["chk.servoPin"] = new[] { "{0}: its signal lead (orange) is not wired to an Uno pin.", "{0}: signal simi (toʻq sariq) Uno pinlaridan biriga ulanmagan.", "{0}: сигнальный провод (оранжевый) не подключён к выводу Uno." },
            ["chk.sonarPin"] = new[] { "The HC-SR04's {0} pin is not wired to an Uno pin.", "HC-SR04 ning {0} pini Uno pinlaridan biriga ulanmagan.", "Вывод {0} датчика HC-SR04 не подключён к выводу Uno." },
            ["chk.inputFloating"] = new[] { "L298N {0} is not wired to the Uno: that input floats.", "L298N ning {0} kirishi Uno ga ulanmagan: bu kirish osilib qolgan.", "Вход {0} драйвера L298N не подключён к Uno: вход «висит»." },
            ["chk.motorOnGpio"] = new[] { "{0} motor is wired to Uno pin {1}: a pin gives 40 mA at most, a TT motor needs up to 1 A. Motors go on the L298N's OUT terminals.", "{0} motor Uno ning {1} piniga ulangan: pin koʻpi bilan 40 mA beradi, TT motorga esa 1 A gacha kerak. Motorlar L298N ning OUT chiqishlariga ulanadi.", "{0} мотор подключён к выводу {1} платы Uno: вывод даёт не больше 40 мА, а мотору TT нужно до 1 А. Моторы подключают к выходам OUT драйвера L298N." },
            ["chk.motorNotConnected"] = new[] { "{0} motor is not connected: put M+ and M− on OUT1 and OUT2, or on OUT3 and OUT4.", "{0} motor ulanmagan: M+ va M− ni OUT1 va OUT2 ga yoki OUT3 va OUT4 ga ulang.", "{0} мотор не подключён: подключите M+ и M− к OUT1 и OUT2 или к OUT3 и OUT4." },
